public class ClassX {
    /**
     * Kinnitab tokeni päist, et tagada algoritmi toetamine.
     * 
     * Funktsioon kontrollib, kas päise 'alg' väli sisaldab 'HS256'.
     */
    public static boolean isAlgorithmSupported(Map<String, String> token) {
        if (token.containsKey("alg")) {
            return "HS256".equals(token.get("alg"));
        }
        return false;
    }
}
