import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Bir arşivden belirli bir üyeyi çıkarır (simüle edilmiş).
     * 
     * Fonksiyon, mutlak yolları önlemek için üye adının bir eğik çizgi ile başlayıp başlamadığını kontrol eder.
     */
    public static void extractFileFromArchive(String archivePath, String entryName) throws Exception {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            throw new FileNotFoundException("Arşiv dosyası bulunamadı: " + archivePath);
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                if (entry.getName().equals(entryName)) {
                    File destFile = new File(entryName);
                    if (!destFile.getParentFile().exists()) {
                        destFile.getParentFile().mkdirs();
                    }
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                    System.out.println("Üye çıkarıldı: " + entryName);
                    return;
                }
                zis.closeEntry();
            }
            System.out.println("Üye bulunamadı: " + entryName);
        }
    }
}
