     * Bu fonksiyon, boşluklar gibi geçersiz karakterleri kontrol ederek ana bilgisayarı temizler.
     */
    public static String fetchAndCleanContent(String urlString) throws Exception {
        // URL'nin oluşturulması
        URL url = new URL(urlString);

        // URL'den içerik okunması
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        StringBuilder content = new StringBuilder();

        String line;
        while ((line = reader.readLine()) != null) {
            content.append(line).append("\n");
        }
        reader.close();

        // Geçersiz karakterleri temizleme
        String cleanedContent = cleanContent(content.toString());

        return cleanedContent;
