public class ClassX {
    /**
     * يسترجع المحتوى من عنوان URL تم إنشاؤه بعد التحقق من صحة المضيف.
     * 
     * تقوم هذه الوظيفة بتنظيف المضيف من خلال التحقق من وجود أحرف غير صالحة مثل المسافات.
     */
    public static String getContentFromURL(String urlStr) {
