            // Create a URL object from the input string
            URL url = new URL(urlStr);

            // Clean the host by removing any non-alphanumeric characters except dots
            String cleanedHost = cleanHost(url.getHost());

            // Construct the cleaned URL
            URL cleanedUrl = new URL(cleanedHost, url.getPath(), url.getQuery());

            // Open a connection to the cleaned URL
            java.net.HttpURLConnection conn = (java.net.HttpURLConnection) cleanedUrl.openConnection();
            conn.setRequestMethod("GET");

            // Get the response code
            int responseCode = conn.getResponseCode();

            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the content from the response
                return readContent(conn.getInputStream());
            } else {
                throw new RuntimeException("Failed to retrieve content. Response code: " + responseCode);
            }
        } catch (MalformedURLException e) {
            throw new RuntimeException("Invalid URL: " + urlStr, e);
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving content from URL: " + urlStr, e);
        }
    }

    private static String cleanHost(String host) {
        // Use regex to remove non-alphanumeric characters except dots
        Pattern pattern = Pattern.compile("[^a-zA-Z0-9.]");
        Matcher matcher = pattern.matcher(host);
        return matcher.replaceAll("");
    }

    private static String readContent(java.io.InputStream inputStream) throws Exception {
        StringBuilder contentBuilder = new StringBuilder();
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            contentBuilder.append(new String(buffer, 0, bytesRead));
        }
        return contentBuilder.toString();
    }
}
