        } else {
            System.out.println("No matching command found for MIME type '" + mimeType + "'.");
        }
    }

    private static String findMatch(String mimeType) {
        // Example data: mime_type, command
        String data = "text/plain, /usr/bin/less\n" +
                     "application/pdf, /usr/bin/acroread\n" +
                     "image/jpeg, /usr/bin/display";

        // Split the data into lines
        String[] lines = data.split("\n");

        // Use regex to match the MIME type
        Pattern pattern = Pattern.compile("^" + Pattern.quote(mimeType) + ",\\s+(.*)$");
        for (String line : lines) {
            Matcher matcher = pattern.matcher(line);
            if (matcher.find()) {
                return matcher.group(1);
            }
        }

        return null;
    }
}
