import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     * 
     * @param input The input string to be sanitized.
     * @return The sanitized string with script tags removed.
     */
    public static String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }
        // Regular expression to match <script> tags
        Pattern scriptTagPattern = Pattern.compile("<script[^>]*>", Pattern.CASE_INSENSITIVE);
        Matcher matcher = scriptTagPattern.matcher(input);
        return matcher.replaceAll("");
    }
}
