        } catch (Exception e) {
            System.err.println("Error al evaluar la expresión: " + e.getMessage());
        }
    }

    private static String sanitizeExpression(String expression) {
        // Bloquea palabras clave peligrosas
        String[] blockedKeywords = {"eval", "setTimeout", "setInterval", "with", "delete", "var", "let", "const"};
        for (String keyword : blockedKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Expresión no permitida: contiene palabras clave peligrosas.");
            }
        }
        return expression;
    }
}
