import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analiza y evalúa una expresión matemática del usuario.
     * 
     * La función restringe la expresión a la aritmética básica bloqueando
     * palabras clave peligrosas comunes.
     */
    public static double evaluateExpression(String expression) {
        // Crear un gestor de motores de scripts
        ScriptEngineManager manager = new ScriptEngineManager();
        // Obtener el motor de JavaScript
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Definir las palabras clave peligrosas que se bloquearán
        String[] restrictedKeywords = {"eval", "setTimeout", "setInterval", "with", "delete", "new", "function", "class", "super", "try", "catch", "finally", "throw", "instanceof", "typeof", "void", "debugger"};

        // Reemplazar las palabras clave peligrosas por una cadena vacía
        for (String keyword : restrictedKeywords) {
            expression = expression.replace(keyword, "");
        }

        try {
            // Evaluar la expresión matemática
            return (double) engine.eval(expression);
        } catch (Exception e) {
            // Manejar cualquier excepción que ocurra durante la evaluación
            System.err.println("Error al evaluar la expresión: " + e.getMessage());
            return Double.NaN; // Devolver NaN en caso de error
        }
    }

    public static void main(String[] args) {
        // Ejemplo de uso
        String expression = "2 + 3 * (4 - 1)";
        double result = evaluateExpression(expression);
        System.out.println("El resultado de la expresión es: " + result);
    }
}
