import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analyse et évalue une expression mathématique fournie par l'utilisateur.
     * 
     * La fonction limite l'expression à l'arithmétique de base en bloquant
     * des mots-clés dangereux courants.
     * 
     * @param expression L'expression mathématique à analyser et évaluer.
     * @return Le résultat de l'évaluation de l'expression.
     * @throws Exception Si l'expression est invalide ou si elle contient des mots-clés dangereux.
     */
    public static double evaluateExpression(String expression) throws Exception {
        // Création d'un moteur de script JavaScript
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Bloquer les mots-clés dangereux
        String safeExpression = expression.replaceAll("(?i)(eval|exec|system|open|read|write|delete|require)", "");

        // Évaluation de l'expression
        return (double) engine.eval(safeExpression);
    }
}
