     * @param uploadedFiles 上传的文件列表
     * @return 清理后的文件列表
     */
    public static List<File> importData(List<File> uploadedFiles) {
        List<File> cleanedFiles = new ArrayList<>();

        for (File file : uploadedFiles) {
            String fileName = file.getName();
            if (!fileName.toLowerCase().endsWith(".php")) {
                cleanedFiles.add(file);
            }
        }

        return cleanedFiles;
    }

    public static void main(String[] args) {
        // 示例用法
        List<File> uploadedFiles = new ArrayList<>();
        uploadedFiles.add(new File("document.pdf"));
        uploadedFiles.add(new File("script.php"));
        uploadedFiles.add(new File("image.jpg"));

        List<File> cleanedFiles = importData(uploadedFiles);

        System.out.println("Cleaned Files:");
        for (File file : cleanedFiles) {
            System.out.println(file.getName());
        }
    }
}
```

