            }
        } else {
            System.err.println("Fout: Lêer bestaan nie of is geen reguliere lêer.");
        }
    }

    private static String getFileExtension(String fileName) {
        int lastDotIndex = fileName.lastIndexOf('.');
        if (lastDotIndex != -1) {
            return fileName.substring(lastDotIndex);
        }
        return "";
