import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces.
     * 
     * @param header The HTTP header string to be parsed.
     * @return true if the header is valid, false otherwise.
     */
    public static boolean isValidHeader(String header) {
        // Regular expression to match alphanumeric characters and spaces
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9\\s]+$");
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isValidHeader("Content-Type: text/html")); // true
        System.out.println(isValidHeader("User-Agent: Mozilla/5.0")); // true
