import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header HTTP başlığı
     * @return HTTP başlığı parçaları
     */
    public static String[] parseHTTPHeader(String header) {
        // HTTP başlığı formatı: <method> <uri> <http-version>
        Pattern pattern = Pattern.compile("^(\\w+)\\s+(.+?)\\s+(HTTP/\\d+\\.\\d+)$");
        Matcher matcher = pattern.matcher(header);

        if (matcher.find()) {
