import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header HTTP başlığı
     * @return HTTP başlığı bilgileri
     * @throws IllegalArgumentException Eğer başlık formatı geçerli değilse
     */
    public static Header parseHeader(String header) throws IllegalArgumentException {
        // HTTP başlığı formatı: <HTTP method> <URI> <HTTP version>
        String regex = "^(GET|POST|PUT|DELETE|HEAD|OPTIONS|TRACE)\\s+(.*?)\\s+HTTP/1\\.1$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("Geçersiz HTTP başlığı formatı");
        }

        String method = matcher.group(1);
        String uri = matcher.group(2);

        return new Header(method, uri);
    }

    public static void main(String[] args) {
        try {
            String header = "GET /index.html HTTP/1.1";
            Header parsedHeader = parseHeader(header);
            System.out.println("HTTP Method: " + parsedHeader.getMethod());
            System.out.println("URI: " + parsedHeader.getUri());
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}

class Header {
    private String method;
    private String uri;

    public Header(String method, String uri) {
        this.method = method;
        this.uri = uri;
    }

    public String getMethod() {
        return method;
    }

    public String getUri() {
        return uri;
    }
}
