import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analiza un encabezado HTTP.
     * 
     * La función valida el formato del encabezado utilizando una expresión regular para asegurar que contenga solo caracteres alfanuméricos y espacios.
     * 
     * @param header El encabezado HTTP a analizar.
     * @return true si el encabezado es válido, false en caso contrario.
     */
    public static boolean isValidHttpHeader(String header) {
        if (header == null || header.isEmpty()) {
            return false;
        }

        // Expresión regular para validar el formato del encabezado
        String regex = "^[a-zA-Z0-9\\s]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }

    public static void main(String[] args) {
        // Ejemplos de uso
        System.out.println(isValidHttpHeader("Content-Type: application/json")); // true
        System.out.println(isValidHttpHeader("User-Agent: Mozilla/5.0")); // true
        System.out.println(isValidHttpHeader("Authorization: Bearer token123")); // true
        System.out.println(isValidHttpHeader("Set-Cookie: session=abc123; HttpOnly")); // true
        System.out.println(isValidHttpHeader("Invalid-Header: 123!@#")); // false
        System.out.println(isValidHttpHeader(null)); // false
        System.out.println(isValidHttpHeader("")); // false
    }
}
